diff --git a/app/src/main/java/com/termux/app/fragments/settings/BasePreferenceFragment.java b/app/src/main/java/com/termux/app/fragments/settings/BasePreferenceFragment.java
new file mode 100644
index 000000000..d445114ed
--- /dev/null
+++ b/app/src/main/java/com/termux/app/fragments/settings/BasePreferenceFragment.java
@@ -0,0 +1,32 @@
+package com.termux.app.fragments.settings;
+
+import android.content.Context;
+import android.os.Bundle;
+
+import androidx.annotation.NonNull;
+import androidx.annotation.XmlRes;
+import androidx.preference.PreferenceDataStore;
+import androidx.preference.PreferenceFragmentCompat;
+
+public abstract class BasePreferenceFragment extends PreferenceFragmentCompat {
+
+    @Override
+    public final void onCreatePreferences(Bundle savedInstanceState, String rootKey) {
+        Context context = getContext();
+        if (context == null) return;
+
+        getPreferenceManager().setPreferenceDataStore(getPreferenceDataStore(context));
+        setPreferencesFromResource(getPreferencesResourceId(), rootKey);
+        onPreferencesLoaded(context);
+    }
+
+    @XmlRes
+    protected abstract int getPreferencesResourceId();
+
+    @NonNull
+    protected abstract PreferenceDataStore getPreferenceDataStore(@NonNull Context context);
+
+    protected void onPreferencesLoaded(@NonNull Context context) {
+    }
+
+}
diff --git a/app/src/main/java/com/termux/app/fragments/settings/LogLevelPreferenceUtils.java b/app/src/main/java/com/termux/app/fragments/settings/LogLevelPreferenceUtils.java
new file mode 100644
index 000000000..19a474a1d
--- /dev/null
+++ b/app/src/main/java/com/termux/app/fragments/settings/LogLevelPreferenceUtils.java
@@ -0,0 +1,45 @@
+package com.termux.app.fragments.settings;
+
+import android.content.Context;
+
+import androidx.annotation.NonNull;
+import androidx.preference.ListPreference;
+import androidx.preference.PreferenceCategory;
+import androidx.preference.PreferenceFragmentCompat;
+
+import com.termux.shared.logger.Logger;
+
+public final class LogLevelPreferenceUtils {
+
+    private static final String LOGGING_CATEGORY_KEY = "logging";
+    private static final String LOG_LEVEL_KEY = "log_level";
+
+    private LogLevelPreferenceUtils() {
+    }
+
+    public static void configureLogLevelPreference(@NonNull PreferenceFragmentCompat fragment,
+                                                   @NonNull Context context,
+                                                   int logLevel) {
+        PreferenceCategory loggingCategory = fragment.findPreference(LOGGING_CATEGORY_KEY);
+        if (loggingCategory == null) return;
+
+        ListPreference logLevelListPreference = fragment.findPreference(LOG_LEVEL_KEY);
+        if (logLevelListPreference == null) return;
+
+        setLogLevelListPreferenceData(logLevelListPreference, context, logLevel);
+        loggingCategory.addPreference(logLevelListPreference);
+    }
+
+    private static void setLogLevelListPreferenceData(@NonNull ListPreference logLevelListPreference,
+                                                      @NonNull Context context,
+                                                      int logLevel) {
+        CharSequence[] logLevels = Logger.getLogLevelsArray();
+        CharSequence[] logLevelLabels = Logger.getLogLevelLabelsArray(context, logLevels, true);
+
+        logLevelListPreference.setEntryValues(logLevels);
+        logLevelListPreference.setEntries(logLevelLabels);
+        logLevelListPreference.setValue(String.valueOf(logLevel));
+        logLevelListPreference.setDefaultValue(Logger.DEFAULT_LOG_LEVEL);
+    }
+
+}
